const originalChallengeQuestion=challengeQuestion;challengeQuestion=function(item){const q=originalChallengeQuestion(item),entry=QUALITY_REASONING.find(([prefix])=>q[0].startsWith(prefix));if(entry){let j=1;q[1]=q[1].map((v,i)=>i===q[2]?entry[1][0]:entry[1][j++])}return q};
