const qualityPractice=startPractice;startPractice=function(subject,review=false){if(!review)return qualityPractice(subject,false);ensureQualityHistory();const now=Date.now(),groups=new Set(),deck=qualityShuffle(profile.missed||[]).map(key=>{const[id,n]=key.split(':');return{id,index:Number(n),q:BANK[id]?.[Number(n)]}}).filter(item=>{if(!item.q||questionMemoryState(item.id,item.index,now)!=='review'||!qualityAvailable(item.id,item.index,now))return false;const group=questionGroup(item);if(groups.has(group)||now-(profile.questionGroupSeen[group]||0)<QUALITY_GROUP_REST)return false;groups.add(group);return true}).slice(0,10);if(!deck.length){toast('Your missed questions and matching templates are resting for at least 48 hours. Try other fields.');return}clearQuestionClock();closeModal();quiz={mode:'practice',deck,pos:0,right:0,subject,timed:!!profile.questionTimed};ask()};
